class Solution:
 def rotatedDigits(self,n):
  good={'0','1','2','5','6','8','9'};changed={'2','5','6','9'};ans=0
  for x in range(1,n+1):
   s=str(x)
   if all(c in good for c in s) and any(c in changed for c in s):ans+=1
  return ans

class Solution:
 def numberOfLines(self,widths,s):
  lines=1;cur=0
  for c in s:
   w=widths[ord(c)-97]
   if cur+w>100:lines+=1;cur=w
   else:cur+=w
  return [lines,cur]

class Solution:
 def subdomainVisits(self,cpdomains):
  counts={}
  for item in cpdomains:
   n,domain=item.split();parts=domain.split('.')
   for i in range(len(parts)):key='.'.join(parts[i:]);counts[key]=counts.get(key,0)+int(n)
  return [f'{v} {k}' for k,v in counts.items()]

import re
from collections import Counter
class Solution:
 def mostCommonWord(self,paragraph,banned):
  blocked=set(banned);words=[w for w in re.findall(r'[a-z]+',paragraph.lower()) if w not in blocked]
  return Counter(words).most_common(1)[0][0]

class Solution:
 def shortestToChar(self,s,c):
  n=len(s);ans=[n]*n;last=-n
  for i,ch in enumerate(s):
   if ch==c:last=i
   ans[i]=i-last
  last=2*n
  for i in range(n-1,-1,-1):
   if s[i]==c:last=i
   ans[i]=min(ans[i],last-i)
  return ans

class Solution:
 def toGoatLatin(self,sentence):
  out=[];vowels=set('aeiouAEIOU')
  for i,w in enumerate(sentence.split(),1):
   if w[0] not in vowels:w=w[1:]+w[0]
   out.append(w+'ma'+'a'*i)
  return ' '.join(out)

class Solution:
 def largeGroupPositions(self,s):
  out=[];i=0
  while i<len(s):
   j=i
   while j<len(s) and s[j]==s[i]:j+=1
   if j-i>=3:out.append([i,j-1])
   i=j
  return out

